#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RuntimeAcpTerminalExitStatus {
    exit_code: Option<u32>,
    signal: Option<String>,
}

impl RuntimeAcpTerminalExitStatus {
    pub fn exit_code(&self) -> Option<u32> {
        self.exit_code
    }

    pub fn signal(&self) -> Option<&str> {
        self.signal.as_deref()
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RuntimeAcpTerminalOutput {
    output: String,
    truncated: bool,
    exit_status: Option<RuntimeAcpTerminalExitStatus>,
}

impl RuntimeAcpTerminalOutput {
    pub fn output(&self) -> &str {
        &self.output
    }

    pub fn truncated(&self) -> bool {
        self.truncated
    }

    pub fn exit_status(&self) -> Option<&RuntimeAcpTerminalExitStatus> {
        self.exit_status.as_ref()
    }
}

impl RuntimeAcpTerminalHandle {
    pub fn terminal_id(&self) -> &str {
        &self.terminal_id
    }

    pub fn close(mut self) -> io::Result<()> {
        self.cleanup()
    }

    pub fn output(&self) -> io::Result<RuntimeAcpTerminalOutput> {
        self.handler
            .observe_terminal(
                &self.request,
                self.terminal_id.clone(),
                surface::SurfaceCapabilityCallKind::TerminalOutput,
            )
            .and_then(|result| match result {
                RuntimeAcpTerminalObservation::Output(output) => Ok(output),
                RuntimeAcpTerminalObservation::Exit(_) => Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "runtime returned terminal exit for an output request",
                )),
            })
    }

    pub fn wait_for_exit(&self) -> io::Result<RuntimeAcpTerminalExitStatus> {
        self.handler
            .observe_terminal(
                &self.request,
                self.terminal_id.clone(),
                surface::SurfaceCapabilityCallKind::TerminalWaitForExit,
            )
            .and_then(|result| match result {
                RuntimeAcpTerminalObservation::Exit(status) => Ok(status),
                RuntimeAcpTerminalObservation::Output(_) => Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "runtime returned terminal output for a wait request",
                )),
            })
    }

    fn cleanup(&mut self) -> io::Result<()> {
        if self.cleanup_started {
            return Ok(());
        }
        self.cleanup_started = true;
        self.handler
            .cleanup_terminal(&self.request, self.terminal_id.clone())
    }
}

pub(crate) enum RuntimeAcpTerminalObservation {
    Output(RuntimeAcpTerminalOutput),
    Exit(RuntimeAcpTerminalExitStatus),
}

fn apply_runtime_actor_reply_effect(effect: RuntimeActorEffect) {
    match effect {
        RuntimeActorEffect::CommitCapability(_) => {
            unreachable!("capability commit effects require the runtime actor")
        }
        RuntimeActorEffect::ReplyCapability(reply) => match reply {
            CapabilityReply::ReadTextFile { reply, result } => {
                let _ = reply.send(result);
            }
            CapabilityReply::WriteTextFile { reply, result } => {
                let _ = reply.send(result);
            }
            CapabilityReply::TerminalCreate { reply, result } => {
                let _ = reply.send(result);
            }
            CapabilityReply::TerminalObservation { reply, result } => {
                let _ = reply.send(result);
            }
            CapabilityReply::TerminalCleanup { reply, result } => {
                let _ = reply.send(result);
            }
        },
        RuntimeActorEffect::ReplyOperation {
            reply,
            result,
            nonblocking,
        } => {
            if nonblocking {
                let _ = reply.try_send(result);
            } else {
                let _ = reply.send(result);
            }
        }
    }
}

fn apply_optional_runtime_actor_reply_effect(effect: Option<RuntimeActorEffect>) {
    if let Some(effect) = effect {
        apply_runtime_actor_reply_effect(effect);
    }
}

impl Drop for RuntimeAcpTerminalHandle {
    fn drop(&mut self) {
        let _ = self.cleanup();
    }
}

impl RuntimeSurfaceReadTextFileHandler {
    fn read_text_file(
        &self,
        request: &orca_core::tool_types::ToolRequest,
        path: PathBuf,
        line: Option<u32>,
        limit: Option<u32>,
    ) -> io::Result<String> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceRequestAcpReadTextFile {
                fence: self.fence.clone(),
                request: request.clone(),
                path,
                line,
                limit,
                reply: reply_tx,
            })
            .map_err(|error| match error {
                TrySendError::Full(_) => io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "runtime capability mailbox is full",
                ),
                TrySendError::Closed(_) => io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    "runtime capability actor is unavailable",
                ),
            })?;
        reply_rx.recv().map_err(|_| {
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                "runtime capability actor closed before read settlement",
            )
        })?
    }
}

