#[derive(Debug)]
struct RuntimeSurfaceProviderResponseIngress {
    command_tx: tokio_mpsc::Sender<ThreadCommand>,
    fence: surface::SurfaceOperationFence,
}

impl surface::RuntimeProviderResponseIngress for RuntimeSurfaceProviderResponseIngress {
    fn commit_response(
        &self,
        response: &crate::model_response::RuntimeModelResponse,
    ) -> io::Result<()> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitProviderResponse {
                fence: self.fence.clone(),
                response: response.clone(),
                reply: reply_tx,
            })
            .map_err(|error| match error {
                TrySendError::Full(_) => io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "runtime semantic ingress mailbox is full",
                ),
                TrySendError::Closed(_) => io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    "runtime semantic ingress actor is unavailable",
                ),
            })?;
        reply_rx.recv().map_err(|_| {
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                "runtime semantic ingress actor closed before commit acknowledgement",
            )
        })?
    }

    fn commit_provider_failure(
        &self,
        identity: &orca_core::thread_item_projection::ModelResponseIdentity,
        message: &str,
    ) -> io::Result<()> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitProviderFailure {
                fence: self.fence.clone(),
                identity: identity.clone(),
                message: message.to_string(),
                reply: reply_tx,
            })
            .map_err(surface_semantic_ingress_send_error)?;
        reply_rx
            .recv()
            .map_err(|_| surface_semantic_ingress_ack_error())?
    }

    fn commit_provider_attempt_failure(
        &self,
        identity: &orca_core::thread_item_projection::ModelResponseIdentity,
        message: &str,
    ) -> io::Result<()> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitProviderAttemptFailure {
                fence: self.fence.clone(),
                identity: identity.clone(),
                message: message.to_string(),
                reply: reply_tx,
            })
            .map_err(surface_semantic_ingress_send_error)?;
        reply_rx
            .recv()
            .map_err(|_| surface_semantic_ingress_ack_error())?
    }

    fn commit_provider_step(
        &self,
        identity: &orca_core::thread_item_projection::ModelResponseIdentity,
        step: &ProviderStep,
    ) -> io::Result<()> {
        self.commit_provider_steps(identity, std::slice::from_ref(step))
    }

    fn commit_provider_steps(
        &self,
        identity: &orca_core::thread_item_projection::ModelResponseIdentity,
        steps: &[ProviderStep],
    ) -> io::Result<()> {
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitProviderStep {
                fence: self.fence.clone(),
                identity: identity.clone(),
                steps: steps.to_vec(),
                reply: None,
            })
            .map_err(|error| match error {
                TrySendError::Full(_) => io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "runtime semantic ingress mailbox is full",
                ),
                TrySendError::Closed(_) => io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    "runtime semantic ingress actor is unavailable",
                ),
            })?;
        Ok(())
    }

    fn commit_tool_results(&self, results: &[orca_core::tool_types::ToolResult]) -> io::Result<()> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitToolResults {
                fence: self.fence.clone(),
                results: results.to_vec(),
                reply: reply_tx,
            })
            .map_err(|error| match error {
                TrySendError::Full(_) => io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "runtime semantic ingress mailbox is full",
                ),
                TrySendError::Closed(_) => io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    "runtime semantic ingress actor is unavailable",
                ),
            })?;
        reply_rx.recv().map_err(|_| {
            io::Error::new(
                io::ErrorKind::BrokenPipe,
                "runtime semantic ingress actor closed before commit acknowledgement",
            )
        })?
    }

    fn commit_plan_update(&self, update: &orca_core::plan_types::UpdatePlanArgs) -> io::Result<()> {
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        self.command_tx
            .try_send(ThreadCommand::SurfaceCommitPlanUpdate {
                fence: self.fence.clone(),
                update: update.clone(),
                reply: reply_tx,
            })
            .map_err(surface_semantic_ingress_send_error)?;
        reply_rx
            .recv()
            .map_err(|_| surface_semantic_ingress_ack_error())?
    }
}

