pub struct RuntimeThreadStartRequest {
    config: RunConfig,
    title: String,
    preloaded: Option<SessionTranscript>,
    inherited_conversation: Option<Conversation>,
    parent_thread_id: Option<String>,
    mcp_registry: Option<McpRegistry>,
    prepared_record_meta: Option<SessionMeta>,
    prepared_runtime_thread_id: Option<String>,
    ephemeral_one_shot: Option<surface::FirstOperationCompletionPolicy>,
    ephemeral_reservation_timeout: Duration,
    #[cfg(test)]
    ephemeral_close_commit_failures: usize,
    replace_resume_scope: bool,
}

impl RuntimeThreadStartRequest {
    pub fn new(mut config: RunConfig, title: impl Into<String>) -> Self {
        config.additional_working_directories.retain(|directory| {
            directory.source != crate::runtime_permission::SESSION_METADATA_DIRECTORY_SOURCE
        });
        Self {
            config,
            title: title.into(),
            preloaded: None,
            inherited_conversation: None,
            parent_thread_id: None,
            mcp_registry: None,
            prepared_record_meta: None,
            prepared_runtime_thread_id: None,
            ephemeral_one_shot: None,
            ephemeral_reservation_timeout: Duration::from_millis(
                surface::SURFACE_RESERVATION_LEASE_MS,
            ),
            #[cfg(test)]
            ephemeral_close_commit_failures: 0,
            replace_resume_scope: false,
        }
    }

    pub fn with_preloaded(mut self, preloaded: SessionTranscript) -> Self {
        self.preloaded = Some(preloaded);
        self
    }

    fn with_attached_side_context(
        mut self,
        parent_thread_id: impl Into<String>,
        conversation: Conversation,
    ) -> Self {
        self.config.history_mode = HistoryMode::Disabled;
        self.config.auto_memory = false;
        self.config.approval_mode = ApprovalMode::Plan;
        self.inherited_conversation = Some(conversation);
        self.parent_thread_id = Some(parent_thread_id.into());
        self
    }

    pub fn with_mcp_registry(mut self, mcp_registry: McpRegistry) -> Self {
        self.mcp_registry = Some(mcp_registry);
        self
    }

    pub fn with_ephemeral_non_catalogued_one_shot(
        mut self,
        close_after: surface::FirstOperationCompletionPolicy,
    ) -> Self {
        self.ephemeral_one_shot = Some(close_after);
        self
    }

    pub(crate) fn with_resume_scope_replacement(mut self) -> Self {
        self.replace_resume_scope = true;
        self
    }

    fn start(self) -> io::Result<RuntimeThread> {
        let inherited_conversation = self.inherited_conversation;
        let mcp_registry = self
            .mcp_registry
            .unwrap_or_else(|| orca_mcp::initialize_registry(&self.config.mcp_servers));
        let mut thread = RuntimeThread::start_with_prepared_history_and_runtime_id(
            &self.config,
            self.title,
            self.preloaded,
            mcp_registry,
            self.prepared_record_meta,
            self.prepared_runtime_thread_id,
        )?;
        if let Some(mut conversation) = inherited_conversation {
            conversation.internal_context = Default::default();
            conversation.add_system_pinned(SIDE_CONVERSATION_BOUNDARY.to_string());
            *thread.session_mut().conversation_mut() = conversation;
        }
        Ok(thread)
    }

    fn prepare(mut self) -> Result<PreparedRuntimeThreadStart, RuntimeHostError> {
        if self.inherited_conversation.is_some() {
            if !matches!(self.config.history_mode, HistoryMode::Disabled) {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "attached side conversation requires disabled history".to_string(),
                });
            }
            self.parent_thread_id.as_deref().ok_or_else(|| {
                RuntimeHostError::ThreadStartFailed {
                    message: "attached side conversation requires a parent thread".to_string(),
                }
            })?;
            let raw_thread_id = uuid::Uuid::now_v7();
            let thread_id = raw_thread_id.to_string();
            let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(
                *raw_thread_id.as_bytes(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid attached surface thread identity: {error:?}"),
            })?;
            let owner_lease = surface::ExclusiveOwnerLease::acquire_process_local_thread(
                surface_thread_id.clone(),
                &HostSurfaceClock::now(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to acquire attached surface owner lease: {error:?}"),
            })?;
            self.config.subagents.max_depth = 0;
            self.config.subagents.max_parallel = 1;
            self.prepared_runtime_thread_id = Some(thread_id.clone());
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: Some(PreparedSurfaceOwner {
                    thread_id,
                    surface_thread_id,
                    owner_lease,
                    persistence: PreparedSurfacePersistence::EphemeralAttached,
                }),
                resume_scope_replacement: None,
            });
        }
        if let Some(close_after) = self.ephemeral_one_shot {
            if !matches!(self.config.history_mode, HistoryMode::Disabled) {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "ephemeral one-shot surface requires disabled history".to_string(),
                });
            }
            self.config.auto_memory = false;
            let raw_thread_id = uuid::Uuid::now_v7();
            let thread_id = raw_thread_id.to_string();
            let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(
                *raw_thread_id.as_bytes(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid ephemeral surface thread identity: {error:?}"),
            })?;
            let owner_lease = surface::ExclusiveOwnerLease::acquire_process_local_thread(
                surface_thread_id.clone(),
                &HostSurfaceClock::now(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to acquire ephemeral surface owner lease: {error:?}"),
            })?;
            self.prepared_runtime_thread_id = Some(thread_id.clone());
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: Some(PreparedSurfaceOwner {
                    thread_id,
                    surface_thread_id,
                    owner_lease,
                    persistence: PreparedSurfacePersistence::EphemeralNonCataloguedOneShot {
                        close_after,
                    },
                }),
                resume_scope_replacement: None,
            });
        }
        let (thread_id, path) = match self.config.history_mode.clone() {
            HistoryMode::Record => {
                let cwd = self.config.cwd.clone().unwrap_or_else(|| {
                    std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"))
                });
                let meta = SessionStore::new().create_meta_with_permissions(
                    &cwd,
                    self.config.provider.as_str(),
                    self.config.model.as_history_value(),
                    &self.title,
                    self.config.active_permission_profile.clone(),
                    self.config.approval_mode,
                    self.config.permission_rules.clone(),
                    self.config.additional_working_directories.clone(),
                );
                let path =
                    crate::history::prospective_session_path(&meta.session_id, meta.created_at);
                let thread_id = meta.session_id.clone();
                self.prepared_record_meta = Some(meta);
                (thread_id, path)
            }
            HistoryMode::Resume(selector) | HistoryMode::ResumeAt { selector, .. } => {
                let transcript = match self.preloaded.take() {
                    Some(transcript) => transcript,
                    None => SessionStore::new()
                        .load_session(&selector)
                        .map_err(|error| RuntimeHostError::ThreadStartFailed {
                            message: error.to_string(),
                        })?,
                };
                let thread_id = transcript.meta.session_id.clone();
                let path = transcript.path.clone();
                self.preloaded = Some(transcript);
                (thread_id, path)
            }
            HistoryMode::Fork(selector) => {
                let transcript = match self.preloaded.take() {
                    Some(transcript) => transcript,
                    None => SessionStore::new()
                        .load_session(&selector)
                        .map_err(|error| RuntimeHostError::ThreadStartFailed {
                            message: error.to_string(),
                        })?,
                };
                let cwd = self.config.cwd.clone().unwrap_or_else(|| {
                    std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"))
                });
                let store = SessionStore::new();
                let mut meta = store.create_fork_meta(
                    &cwd,
                    self.config.provider.as_str(),
                    self.config.model.as_history_value(),
                    &self.title,
                    transcript.meta.session_id.clone(),
                );
                meta.active_permission_profile = self.config.active_permission_profile.clone();
                meta.approval_mode = Some(self.config.approval_mode);
                meta.permission_rules = self.config.permission_rules.clone();
                meta.additional_working_directories =
                    self.config.additional_working_directories.clone();
                let path =
                    crate::history::prospective_session_path(&meta.session_id, meta.created_at);
                let thread_id = meta.session_id.clone();
                self.prepared_record_meta = Some(meta);
                self.preloaded = Some(transcript);
                (thread_id, path)
            }
            _ => {
                return Ok(PreparedRuntimeThreadStart {
                    request: self,
                    surface_owner: None,
                    resume_scope_replacement: None,
                });
            }
        };
        let Ok(raw_thread_id) = uuid::Uuid::parse_str(&thread_id) else {
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: None,
                resume_scope_replacement: None,
            });
        };
        let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(*raw_thread_id.as_bytes())
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid surface thread identity: {error:?}"),
            })?;
        let owner_lease = surface::ExclusiveOwnerLease::acquire_thread(
            path.with_extension("surface-owner.lock"),
            path.with_extension("surface-owner.epoch"),
            surface_thread_id.clone(),
            &HostSurfaceClock::now(),
        )
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to acquire typed surface owner lease: {error:?}"),
        })?;
        let resume_scope_replacement = (self.replace_resume_scope
            && matches!(
                self.config.history_mode,
                HistoryMode::Resume(_) | HistoryMode::ResumeAt { .. }
            ))
        .then(|| ResumeScopeReplacement {
            runtime_workspace_roots: self
                .config
                .runtime_workspace_roots
                .clone()
                .unwrap_or_else(|| self.config.cwd.clone().into_iter().collect::<Vec<_>>()),
            additional_working_directories: self.config.additional_working_directories.clone(),
        });
        Ok(PreparedRuntimeThreadStart {
            request: self,
            surface_owner: Some(PreparedSurfaceOwner {
                thread_id,
                surface_thread_id,
                owner_lease,
                persistence: PreparedSurfacePersistence::Recorded { path },
            }),
            resume_scope_replacement,
        })
    }
}

struct PreparedRuntimeThreadStart {
    request: RuntimeThreadStartRequest,
    surface_owner: Option<PreparedSurfaceOwner>,
    resume_scope_replacement: Option<ResumeScopeReplacement>,
}

struct ResumeScopeReplacement {
    runtime_workspace_roots: Vec<std::path::PathBuf>,
    additional_working_directories: Vec<orca_core::config::AdditionalWorkingDirectory>,
}

struct PreparedSurfaceOwner {
    thread_id: String,
    surface_thread_id: surface::SurfaceThreadId,
    owner_lease: surface::ExclusiveOwnerLease,
    persistence: PreparedSurfacePersistence,
}

enum PreparedSurfacePersistence {
    Recorded {
        path: std::path::PathBuf,
    },
    EphemeralNonCataloguedOneShot {
        close_after: surface::FirstOperationCompletionPolicy,
    },
    EphemeralAttached,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RuntimeThreadMutation {
    SetModel(Option<String>),
    AddPinnedContext(String),
    ReplaceSkillContext(Option<String>),
}

impl RuntimeThreadMutation {
    fn apply(self, thread: &mut RuntimeThread) {
        match self {
            Self::SetModel(model) => thread.session_mut().set_model(model.as_deref()),
            Self::AddPinnedContext(content) => thread.session_mut().add_pinned_context(content),
            Self::ReplaceSkillContext(content) => {
                thread.session_mut().replace_skill_context(content);
            }
        }
    }
}

#[derive(Clone, Debug)]
pub struct RuntimeThreadSnapshot {
    thread_id: String,
    session_id: Option<String>,
    conversation: Conversation,
    conversation_records: Option<Vec<crate::thread_store::StoredConversationRecord>>,
    usage_totals: UsageTotals,
    completion_error: Option<String>,
    has_active_workflows: bool,
    active_task_id: Option<String>,
}

impl RuntimeThreadSnapshot {
    fn from_thread(thread: &RuntimeThread, usage_totals: UsageTotals) -> Self {
        Self {
            thread_id: thread.thread_id().to_string(),
            session_id: thread.session().session_id().map(str::to_string),
            conversation: thread.session().conversation().clone(),
            conversation_records: thread.session().conversation_records(),
            usage_totals,
            completion_error: thread.session().completion_error().map(str::to_string),
            has_active_workflows: thread.session().has_active_workflows(),
            active_task_id: thread
                .lifecycle()
                .active_task()
                .map(|task| task.id().to_string()),
        }
    }

    pub fn thread_id(&self) -> &str {
        &self.thread_id
    }

    pub fn session_id(&self) -> Option<&str> {
        self.session_id.as_deref()
    }

    pub fn messages(&self) -> &[Message] {
        &self.conversation.messages
    }

    pub fn conversation(&self) -> &Conversation {
        &self.conversation
    }

    pub(crate) fn conversation_records(
        &self,
    ) -> Option<&[crate::thread_store::StoredConversationRecord]> {
        self.conversation_records.as_deref()
    }

    pub fn usage_totals(&self) -> UsageTotals {
        self.usage_totals
    }

    pub fn completion_error(&self) -> Option<&str> {
        self.completion_error.as_deref()
    }

    pub fn has_active_workflows(&self) -> bool {
        self.has_active_workflows
    }

    pub fn active_task_id(&self) -> Option<&str> {
        self.active_task_id.as_deref()
    }
}

fn surface_history_messages(
    messages: &[Message],
) -> Result<Vec<crate::runtime_surface::SurfaceHistoryMessage>, RuntimeHostError> {
    messages
        .iter()
        .map(|message| match message {
            Message::System { content, .. } => {
                Ok(crate::runtime_surface::SurfaceHistoryMessage::System {
                    role: crate::runtime_surface::SurfaceHistorySystemRole::System,
                    content: crate::runtime_surface::DisplayText::new(content.clone()),
                })
            }
            Message::User { content, .. } => {
                Ok(crate::runtime_surface::SurfaceHistoryMessage::User {
                    role: crate::runtime_surface::SurfaceHistoryUserRole::User,
                    content: crate::runtime_surface::DisplayText::new(content.clone()),
                })
            }
            Message::Assistant {
                content,
                reasoning_content,
                tool_calls,
                ..
            } => Ok(crate::runtime_surface::SurfaceHistoryMessage::Assistant {
                role: crate::runtime_surface::SurfaceHistoryAssistantRole::Assistant,
                content: content
                    .as_ref()
                    .map(|value| crate::runtime_surface::DisplayText::new(value.clone())),
                reasoning_content: reasoning_content
                    .as_ref()
                    .map(|value| crate::runtime_surface::DisplayText::new(value.clone())),
                tool_calls: tool_calls
                    .iter()
                    .map(|tool_call| {
                        crate::runtime_surface::SurfaceDataValue::Object(vec![
                            crate::runtime_surface::SurfaceDataProperty {
                                name: crate::runtime_surface::DisplayText::new("id"),
                                value: Box::new(crate::runtime_surface::SurfaceDataValue::String(
                                    crate::runtime_surface::DisplayText::new(tool_call.id.clone()),
                                )),
                            },
                            crate::runtime_surface::SurfaceDataProperty {
                                name: crate::runtime_surface::DisplayText::new("name"),
                                value: Box::new(crate::runtime_surface::SurfaceDataValue::String(
                                    crate::runtime_surface::DisplayText::new(
                                        tool_call.function_name.clone(),
                                    ),
                                )),
                            },
                            crate::runtime_surface::SurfaceDataProperty {
                                name: crate::runtime_surface::DisplayText::new("arguments"),
                                value: Box::new(crate::runtime_surface::SurfaceDataValue::String(
                                    crate::runtime_surface::DisplayText::new(
                                        tool_call.arguments.clone(),
                                    ),
                                )),
                            },
                        ])
                    })
                    .collect(),
            }),
            Message::Tool {
                tool_call_id,
                content,
                ..
            } => {
                let id = crate::runtime_surface::SurfaceHistoryId::try_new(tool_call_id.clone())
                    .map_err(|error| RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid persisted tool call id: {error:?}"),
                    })?;
                Ok(crate::runtime_surface::SurfaceHistoryMessage::Tool {
                    role: crate::runtime_surface::SurfaceHistoryToolRole::Tool,
                    tool_call_id: id,
                    content: crate::runtime_surface::DisplayText::new(content.clone()),
                })
            }
        })
        .collect()
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum OperationOutcome {
    Completed(RunStatus),
    /// Typed budget/safety stop; the exit code comes from the terminal.
    Stopped(orca_core::budget::OperationTerminal),
    Backgrounded {
        task_id: String,
    },
    ExecutionFailed {
        kind: io::ErrorKind,
        message: String,
    },
    Panicked {
        message: String,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct CompletedTurnOutcome {
    status: RunStatus,
    end_reason: crate::lifecycle::TurnEndReason,
    /// Typed operation terminal; the authoritative fact when present (budget
    /// stops carry `OperationTerminal::Stopped`).
    terminal: Option<orca_core::budget::OperationTerminal>,
    verification: Option<orca_core::verification::VerificationResult>,
}

impl CompletedTurnOutcome {
    fn goal_status(&self) -> orca_core::goal_runtime::GoalTurnStatus {
        // The typed terminal is the fact: a budget stop maps to
        // GoalTurnStatus::BudgetExhausted regardless of the projected status.
        if matches!(
            self.terminal,
            Some(orca_core::budget::OperationTerminal::Stopped { .. })
        ) {
            return orca_core::goal_runtime::GoalTurnStatus::BudgetExhausted;
        }
        match self.status {
            RunStatus::Success => orca_core::goal_runtime::GoalTurnStatus::Success,
            RunStatus::Cancelled => orca_core::goal_runtime::GoalTurnStatus::Cancelled,
            RunStatus::ApprovalRequired => {
                orca_core::goal_runtime::GoalTurnStatus::ApprovalRequired
            }
            RunStatus::Failed | RunStatus::VerificationFailed => {
                orca_core::goal_runtime::GoalTurnStatus::Failed
            }
        }
    }

    fn permits_goal_continuation(&self) -> bool {
        matches!(
            goal_turn_disposition(self.status, self.end_reason, self.terminal.as_ref()),
            GoalTurnDisposition::Advanced | GoalTurnDisposition::Interrupted { .. }
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct OperationTerminal {
    operation_id: OperationId,
    outcome: OperationOutcome,
}

impl OperationTerminal {
    pub fn operation_id(&self) -> OperationId {
        self.operation_id
    }

    pub fn outcome(&self) -> &OperationOutcome {
        &self.outcome
    }
}

#[derive(Clone)]
pub struct OperationCompletion {
    state: Arc<OperationCompletionState>,
}

struct OperationCompletionState {
    terminal: Mutex<Option<OperationTerminal>>,
    completed: Condvar,
}

impl OperationCompletion {
    fn new() -> Self {
        Self {
            state: Arc::new(OperationCompletionState {
                terminal: Mutex::new(None),
                completed: Condvar::new(),
            }),
        }
    }

    pub fn try_terminal(&self) -> Option<OperationTerminal> {
        self.lock_terminal().clone()
    }

    pub fn wait(&self) -> OperationTerminal {
        let mut terminal = self.lock_terminal();
        loop {
            if let Some(terminal) = terminal.clone() {
                return terminal;
            }
            terminal = self
                .state
                .completed
                .wait(terminal)
                .unwrap_or_else(|poisoned| poisoned.into_inner());
        }
    }

    pub fn wait_timeout(&self, timeout: Duration) -> Option<OperationTerminal> {
        let terminal = self.lock_terminal();
        if terminal.is_some() {
            return terminal.clone();
        }
        let (terminal, _) = self
            .state
            .completed
            .wait_timeout_while(terminal, timeout, |terminal| terminal.is_none())
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        terminal.clone()
    }

    fn complete(&self, terminal: OperationTerminal) -> bool {
        let mut current = self.lock_terminal();
        if current.is_some() {
            return false;
        }
        *current = Some(terminal);
        self.state.completed.notify_all();
        true
    }

    fn lock_terminal(&self) -> MutexGuard<'_, Option<OperationTerminal>> {
        self.state
            .terminal
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

pub struct OperationHandle {
    operation_id: OperationId,
    initial_generation: GenerationFence,
    thread: RuntimeThreadHandle,
    completion: OperationCompletion,
}

impl OperationHandle {
    pub fn id(&self) -> OperationId {
        self.operation_id
    }

    pub fn initial_generation(&self) -> GenerationFence {
        self.initial_generation
    }

    pub fn thread_id(&self) -> &str {
        self.thread.thread_id()
    }

    pub fn completion(&self) -> OperationCompletion {
        self.completion.clone()
    }

    pub fn interrupt(&self) -> Result<InterruptOperationResult, RuntimeHostError> {
        self.thread.interrupt_operation(self.operation_id)
    }

    pub fn pause_goal(&self) -> Result<PauseGoalRunResult, RuntimeHostError> {
        self.thread.pause_goal_run(self.operation_id)
    }

    pub fn resume(&self) -> Result<ResumeOperationResult, RuntimeHostError> {
        self.thread.resume_operation(self.operation_id)
    }

    pub fn steer(
        &self,
        input: impl Into<String>,
    ) -> Result<SteerOperationResult, RuntimeHostError> {
        self.thread.steer_operation(self.operation_id, input)
    }

    pub fn admit_generation(
        &self,
        generation: GenerationFence,
    ) -> Result<GenerationAdmissionResult, RuntimeHostError> {
        self.thread.admit_generation(generation)
    }

    pub fn wait(&self) -> OperationTerminal {
        self.completion.wait()
    }

    pub fn wait_timeout(&self, timeout: Duration) -> Option<OperationTerminal> {
        self.completion.wait_timeout(timeout)
    }
}

impl fmt::Debug for OperationHandle {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("OperationHandle")
            .field("thread_id", &self.thread_id())
            .field("operation_id", &self.operation_id)
            .finish_non_exhaustive()
    }
}

